import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"一个实用的 F3 小技巧：减少长时间挖掘时的按键操作","description":"尝试通过 Java 版资源重载保留挖掘输入状态，了解操作步骤、适用限制与停止时的注意事项。","frontmatter":{"title":"一个实用的 F3 小技巧：减少长时间挖掘时的按键操作","description":"尝试通过 Java 版资源重载保留挖掘输入状态，了解操作步骤、适用限制与停止时的注意事项。"},"headers":[],"relativePath":"guides/f3-mining.md","filePath":"guides/f3-mining.md"}`),a={name:`guides/f3-mining.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="一个实用的-f3-小技巧-减少长时间挖掘时的按键操作" tabindex="-1">一个实用的 F3 小技巧：减少长时间挖掘时的按键操作 <a class="header-anchor" href="#一个实用的-f3-小技巧-减少长时间挖掘时的按键操作" aria-label="Permalink to “一个实用的 F3 小技巧：减少长时间挖掘时的按键操作”">​</a></h1><p>长时间挖掘时，一直按着鼠标会有些累。Minecraft Java 版部分环境里，可以尝试利用资源重载过程保留鼠标输入状态；是否成功取决于版本、客户端和输入处理行为。</p><p>这是一种玩家小技巧，没有在本站所涉客户端中完成实测，也不保证所有环境都能复现。</p><h2 id="试一试这五步" tabindex="-1">试一试这五步 <a class="header-anchor" href="#试一试这五步" aria-label="Permalink to “试一试这五步”">​</a></h2><ol><li>按 <strong>F3 + P</strong>，关闭游戏失去焦点时自动暂停的选项，留意聊天栏的状态提示。</li><li>面向需要挖掘的方块，<strong>按住鼠标左键</strong>。</li><li>保持左键按下，同时按 <strong>F3 + T</strong> 触发资源重载。</li><li>等待重载完成，再尝试松开鼠标左键。</li><li>如果客户端保留了挖掘输入，就可能继续挖掘，无需一直按住鼠标。</li></ol><div class="tip custom-block"><p class="custom-block-title">两个快捷键各做什么？</p><p><strong>F3 + P</strong> 切换失去焦点时的自动暂停，影响输入之外的暂停行为，本身不是自动挖矿开关。<strong>F3 + T</strong> 原本用于重载资源，也不是独立的“自动挖矿功能”。</p></div><h2 id="使用时留意" tabindex="-1">使用时留意 <a class="header-anchor" href="#使用时留意" aria-label="Permalink to “使用时留意”">​</a></h2><ul><li>先在安全位置短时间测试，确认工具耐久、背包空间和角色位置。</li><li>连续输入只可能维持挖掘动作，不会替你寻找方块、移动或管理背包。</li><li>不要把维持输入当作可以离开不管的保障；挖空脚下方块、工具损坏等情况仍可能发生。</li><li>在增强生存或科技空岛尝试前，都应遵守对应子服规则。</li></ul><h2 id="怎样停止" tabindex="-1">怎样停止？ <a class="header-anchor" href="#怎样停止" aria-label="Permalink to “怎样停止？”">​</a></h2><p>可先尝试重新按下并松开鼠标左键，观察挖掘是否停止。<strong>这个停止方式同样尚未在当前客户端实测，请先短时验证。</strong></p><p>如果状态仍不确定，退出当前游戏连接后重新进入，确认输入恢复正常再继续。结束后按需要恢复 F3 + P 的暂停选项，并核对聊天栏提示。</p><p>没有复现就保持手动操作，不必反复重载资源。不同客户端可能直接清除按键状态，这是环境差异。</p><p><a href="./">返回玩法知识库</a> · <a href="./../skyblock/commands.html">科技空岛常用命令</a></p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};